<script setup lang="ts">
import {computed,nextTick,onBeforeUnmount,onMounted,ref,watch} from 'vue'
import {ArrowRight,Check,Clock3,Footprints,RefreshCw} from 'lucide-vue-next'
import {journey,clock,nameOf,loadBasket,loadJourney,loadConfirmedRoute,localDate} from '../journey'
import {explorationApi,type PlanningConstraints,type PlanningResult} from '../explorationApi'
import {ApiError} from '../api'
import {memoryEpoch} from '../voiceDraft'
import LocationPicker from './LocationPicker.vue'
const props=defineProps<{tripId:string;revision?:number}>(),emit=defineEmits<{busy:[value:boolean]}>()
const initializing=ref(true),confirming=ref(false),conversation=ref<HTMLElement>()
let disposed=false,requestSequence=0
const busy=ref(false),error=ref(''),result=ref<PlanningResult|null>(null),selected=ref(0),day=ref(''),start=ref(''),end=ref(''),budget=ref(''),rounds=ref(0),cancelled=ref(false)
const submittedHash=ref(''),planningVersion=ref(0)
const form=ref<PlanningConstraints>({business_date:null,starts_at:null,ends_at:null,origin_place_id:null,destination_place_id:null,pace:'standard',objective:'balanced',modes:['walking'],budget_fen:null})
const places=computed(()=>journey.catalog.filter(x=>x.record.kind==='place'))
const editingStep=ref(''),activeStep=ref('date'),earlyTimeConfirmed=ref(false)
const earlyTime=computed(()=>!!start.value&&Number(start.value.slice(0,2))<6)
watch([day,start,end],()=>{earlyTimeConfirmed.value=false})
const missingStep=computed(()=>!day.value?'date':!start.value||!end.value?'time':!(form.value.origin_place_id||form.value.origin_text?.trim())?'origin':!(form.value.destination_place_id||form.value.destination_text?.trim())?'destination':'ready')
const step=computed(()=>editingStep.value||activeStep.value)
const personalMissing=computed(()=>result.value?.issues.some(x=>x.code==='PERSONAL_CHOICE_MISSING'))
const visibleResult=computed(()=>result.value&&!personalMissing.value?result.value:null)
watch([step,visibleResult,busy],async()=>{if(busy.value||initializing.value)return;await nextTick();conversation.value?.querySelector<HTMLElement>('.planning-question,.planning-assessment')?.scrollIntoView({block:'nearest',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})})
const materials=computed(()=>journey.choices.filter(x=>x.status!=='standby'))
const enteringLocations=computed(()=>['origin','destination'].includes(step.value)&&!places.value.length)
const question=computed(()=>enteringLocations.value?'从哪里出发，最后返回哪里？':({date:'你打算哪天去？',time:'当天几点开始，最晚几点结束？',origin:'从哪里出发？',destination:'最后回到哪里？',preferences:'想按什么节奏游玩？',ready:'这些安排合适吗？'}[step.value]||''))
const canContinue=computed(()=>enteringLocations.value?!!(form.value.origin_place_id||form.value.origin_text?.trim())&&!!(form.value.destination_place_id||form.value.destination_text?.trim()):step.value==='date'?!!day.value:step.value==='time'?!!start.value&&!!end.value:step.value==='origin'?!!(form.value.origin_place_id||form.value.origin_text?.trim()):step.value==='destination'?!!(form.value.destination_place_id||form.value.destination_text?.trim()):true)
watch(()=>busy.value||initializing.value,value=>emit('busy',value),{immediate:true})
function chooseDay(offset:number){const date=new Date(localDate()+'T12:00:00+08:00');date.setDate(date.getDate()+offset);day.value=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(date);void advance()}
async function advance(){
 if(!canContinue.value)return
 if(start.value&&end.value&&end.value<=start.value){error.value='结束时间需要晚于开始时间';return}
 await run();if(!error.value){activeStep.value=missingStep.value;editingStep.value=''}
}
function editStep(value:string){editingStep.value=value;error.value=''}
function applyLocation(role:'origin'|'destination',name:string,factId:string|null){form.value[role+'_place_id' as 'origin_place_id'|'destination_place_id']=factId;form.value[role+'_text' as 'origin_text'|'destination_text']=name}
const stale=computed(()=>!!result.value&&(result.value.basket_version!==journey.basketVersion||result.value.trip_version!==journey.trip?.version||submittedHash.value!==JSON.stringify(params())))
const chosenChanges=computed(()=>result.value?.planning?.alternative_changes?.[selected.value]||result.value?.planning?.changes)
const alternatives=computed(()=>result.value?.planning?.result.itineraries||[])
const omitted=(index:number)=>{const chosen=new Set(alternatives.value[index]?.activities.map(x=>result.value?.goal_keys?.[x.goal_id]));return journey.choices.filter(x=>x.status==='standby'||!chosen.has(x.key)&&x.status!=='arranged')}
const params=():PlanningConstraints=>({...form.value,business_date:day.value||null,starts_at:day.value&&start.value?day.value+'T'+start.value+':00+08:00':null,ends_at:day.value&&end.value?day.value+'T'+end.value+':00+08:00':null,budget_fen:budget.value.trim()?Math.round(Number(budget.value)*100):null})
async function run(){success.value=false;if(initializing.value||busy.value||journey.trip?.id!==props.tripId)return;if(earlyTime.value&&!earlyTimeConfirmed.value){editingStep.value='time';error.value='开始时间为凌晨，请核对并确认后继续。';return}busy.value=true;error.value='';cancelled.value=false;result.value=null;const epoch=memoryEpoch.value,id=props.tripId,sequence=++requestSequence
 try{await loadBasket();if(disposed||sequence!==requestSequence||epoch!==memoryEpoch.value||journey.trip?.id!==id)return;if(journey.basketError)throw new Error(journey.basketError);const input=params();submittedHash.value=JSON.stringify(input);const r=await explorationApi.preview(id,journey.trip.version,journey.basketVersion,input,planningVersion.value);if(!disposed&&sequence===requestSequence&&epoch===memoryEpoch.value&&id===props.tripId&&!cancelled.value){result.value=r;planningVersion.value=r.planning_version;rounds.value=r.rounds;selected.value=0}}
 catch(e){if(!disposed&&epoch===memoryEpoch.value&&sequence===requestSequence){error.value=(e as Error).message;if(e instanceof ApiError&&e.status===409)initializing.value=true}}finally{if(!disposed&&epoch===memoryEpoch.value&&sequence===requestSequence)busy.value=false}}
function applyConstraints(c:PlanningConstraints){form.value={...c,modes:[...c.modes]};day.value=c.business_date||'';start.value=c.starts_at?clock(c.starts_at):'';end.value=c.ends_at?clock(c.ends_at):'';budget.value=c.budget_fen!=null?String(c.budget_fen/100):''}
async function answer(reply:{option_id?:string;text?:string}){if(busy.value||stale.value||!journey.trip)return;busy.value=true;error.value='';const guard=memoryEpoch.value,id=props.tripId,sequence=++requestSequence
 try{const saved=await explorationApi.answer(id,journey.trip.version,journey.basketVersion,planningVersion.value,reply);if(disposed||guard!==memoryEpoch.value||sequence!==requestSequence||journey.trip?.id!==id)return;planningVersion.value=saved.version;rounds.value=saved.rounds;applyConstraints(saved.constraints!);result.value=null;await loadBasket();busy.value=false;await run()}
 catch(e){if(!disposed&&guard===memoryEpoch.value&&sequence===requestSequence){error.value=(e as Error).message;if(e instanceof ApiError&&e.status===409)initializing.value=true}}
 finally{if(!disposed&&guard===memoryEpoch.value&&sequence===requestSequence)busy.value=false}}
async function choose(option:PlanningResult['options'][number]){if(option.kind==='constraints'){editStep('time');return}await answer({option_id:option.id})}

async function confirm(){const p=result.value?.planning;if(!p?.candidate_id||stale.value||busy.value)return;confirming.value=true;busy.value=true;error.value='';const epoch=memoryEpoch.value
 try{await explorationApi.confirm(props.tripId,p.base_version,p.candidate_id,selected.value);if(disposed||epoch!==memoryEpoch.value||journey.trip?.id!==props.tripId)return;result.value=null;await loadJourney(true);await loadConfirmedRoute();error.value='';success.value=true}catch(e){if(!disposed&&epoch===memoryEpoch.value)error.value=(e as Error).message}finally{if(!disposed&&epoch===memoryEpoch.value){busy.value=false;confirming.value=false}}}
const success=ref(false)
function resetLocal(){requestSequence++;busy.value=false;cancelled.value=true;result.value=null;success.value=false;error.value=''}
async function cancel(){if(confirming.value)return;const version=planningVersion.value;resetLocal();if(!journey.trip)return;busy.value=true;const guard=memoryEpoch.value
 try{const saved=await explorationApi.cancel(props.tripId,journey.trip.version,journey.basketVersion,version);if(!disposed&&guard===memoryEpoch.value){planningVersion.value=saved.version;rounds.value=0}}catch(e){if(!disposed&&guard===memoryEpoch.value){error.value=(e as Error).message;initializing.value=true}}finally{if(!disposed&&guard===memoryEpoch.value)busy.value=false}}
async function initialize(){error.value='';initializing.value=true;const epoch=memoryEpoch.value,id=props.tripId,sequence=++requestSequence
 try{await loadJourney();if(journey.trip?.id!==id)throw new Error('当前旅程已变化，请重新打开规划');const draft=journey.trip.draft;const saved=await explorationApi.constraints(id);if(disposed||sequence!==requestSequence||epoch!==memoryEpoch.value||journey.trip?.id!==id)return;const c=saved.constraints;applyConstraints(c||{business_date:draft.business_date,starts_at:draft.starts_at,ends_at:draft.ends_at,origin_place_id:draft.origin_place_id,destination_place_id:draft.destination_place_id,pace:draft.pace||'standard',objective:draft.objective||'balanced',modes:[...draft.modes],budget_fen:null});planningVersion.value=saved.version;rounds.value=saved.rounds;result.value=saved.result;submittedHash.value=JSON.stringify(params());activeStep.value=missingStep.value;initializing.value=false}
 catch(e){if(!disposed&&epoch===memoryEpoch.value)error.value='规划条件未加载完成：'+(e as Error).message}}
watch(()=>props.revision,()=>void initialize())
onMounted(initialize)
onBeforeUnmount(()=>{disposed=true;requestSequence++})
watch(memoryEpoch,()=>{resetLocal();error.value='记录已清除';busy.value=false})
</script>
<template><section ref="conversation" class="basket-planning conversation-planning" aria-label="素材篮规划协商">
 <div class="planning-materials"><p v-if="materials.length">这次想去、想吃的：<strong>{{materials.map(x=>x.name).join('、')}}</strong></p><p v-else>接着安排这一程</p><RouterLink to="/basket">调整素材</RouterLink></div>
 <p v-if="initializing" role="status">正在接上你的安排…</p>
 <template v-else-if="!success">
 <div v-if="day||start||form.origin_place_id||form.destination_place_id||form.origin_text||form.destination_text" class="planning-known" aria-label="已提供的安排">
  <button v-if="day" type="button" :disabled="busy" @click="editStep('date')">{{day}}</button>
  <button v-if="start&&end" type="button" :disabled="busy" @click="editStep('time')">{{start}}—{{end}}</button>
  <button v-if="form.origin_place_id||form.origin_text" type="button" :disabled="busy" @click="editStep('origin')">从{{form.origin_place_id?nameOf(form.origin_place_id):form.origin_text}}</button>
  <button v-if="form.destination_place_id||form.destination_text" type="button" :disabled="busy" @click="editStep('destination')">回到{{form.destination_place_id?nameOf(form.destination_place_id):form.destination_text}}</button>
  <button type="button" :disabled="busy" @click="editStep('preferences')">{{{relaxed:'轻松',standard:'适中',compact:'紧凑'}[form.pace]}} · {{{walking:'步行',driving:'驾车',transit:'公共交通'}[form.modes[0]]}}</button>
 </div>
 <form v-if="!visibleResult||editingStep" class="planning-question" @submit.prevent="advance">
  <p class="planning-question-text">{{question}}</p>
  <template v-if="step==='date'"><div class="planning-quick"><button type="button" :disabled="busy" @click="chooseDay(0)">今天</button><button type="button" :disabled="busy" @click="chooseDay(1)">明天</button></div><label>旅行日期<input v-model="day" type="date" required :disabled="busy"></label></template>
  <div v-else-if="step==='time'" class="planning-time-pair"><label>开始时间<input v-model="start" type="time" required :disabled="busy"></label><label>最晚结束<input id="planning-end" v-model="end" type="time" required :disabled="busy"></label></div>
  <template v-else-if="step==='origin'||step==='destination'">
   <label v-if="places.length">{{step==='origin'?'出发地点':'返程地点'}}<select :value="step==='origin'?form.origin_place_id:form.destination_place_id" :disabled="busy" @change="step==='origin'?form.origin_place_id=($event.target as HTMLSelectElement).value:form.destination_place_id=($event.target as HTMLSelectElement).value"><option :value="null">请选择地点</option><option v-for="p in places" :key="p.record.fact_id" :value="p.record.fact_id">{{p.record.name}}</option></select></label>
   <div class="planning-location-fields">
    <label>{{places.length?'或查找其他出发地点':'出发地点'}}<input v-model="form.origin_text" @input="form.origin_place_id=null" type="text" maxlength="120" placeholder="车站、酒店或具体地址" :required="(enteringLocations||step==='origin')&&!form.origin_place_id" :disabled="busy"></label>
    <LocationPicker :query="form.origin_text||''" label="出发地点" :disabled="busy" @confirmed="(name,factId)=>applyLocation('origin',name,factId)"/>
    <label>{{places.length?'或查找其他返回地点':'返回地点'}}<input v-model="form.destination_text" @input="form.destination_place_id=null" type="text" maxlength="120" placeholder="最后回到哪里" :required="(enteringLocations||step==='destination')&&!form.destination_place_id" :disabled="busy"></label>
    <LocationPicker :query="form.destination_text||''" label="返回地点" :disabled="busy" @confirmed="(name,factId)=>applyLocation('destination',name,factId)"/>
   </div>
  </template>
  <template v-else-if="step==='preferences'"><label>交通方式<select v-model="form.modes[0]" :disabled="busy"><option value="walking">步行</option><option value="driving">驾车</option><option value="transit">公共交通</option></select></label><label>游玩节奏<select v-model="form.pace" :disabled="busy"><option value="relaxed">轻松</option><option value="standard">适中</option><option value="compact">紧凑</option></select></label><label>更看重<select v-model="form.objective" :disabled="busy"><option value="balanced">综合平衡</option><option value="less_walking">少走路</option><option value="less_waiting">少等待</option><option value="lower_cost">控制费用</option></select></label><label>预算上限（选填）<input v-model="budget" type="number" min="0" max="1000000" placeholder="人民币" :disabled="busy"></label></template>
  <label v-if="earlyTime" class="early-time-confirm"><input v-model="earlyTimeConfirmed" type="checkbox" :disabled="busy">确认 {{start}} 为实际的凌晨出发时间（北京时间）</label>
  <button class="button primary" :disabled="busy||!canContinue">{{busy?'正在整理…':step==='ready'?'生成安排':'继续'}}<ArrowRight :size="16"/></button>
 </form></template>
<p v-if="busy" role="status">{{confirming?'正在提交已确认的方案…':'正在检查目标、时间和交通资料…'}}</p><p v-if="error" class="error-state" role="alert">{{error}}<button v-if="initializing" type="button" @click="initialize">重新读取条件</button></p><section v-if="success" class="planning-success" role="status"><Check :size="24"/><h3>已确认并更新正式路线</h3><RouterLink :to="'/city-trip/'+tripId" class="button primary">查看行程</RouterLink></section><section v-if="result&&!personalMissing&&!editingStep" class="planning-assessment" :class="result.status" aria-label="规划检测结果"><span class="assessment-status">{{result.status==='feasible'?'已有经过校验的候选':result.status==='infeasible'?'需要你决定取舍':'信息不足 · 待添加'}}</span><h3>{{result.reply}}</h3><div v-if="(form.origin_text||form.destination_text)&&!form.origin_place_id" class="location-recheck"><button type="button" class="text-link" :disabled="busy" @click="editStep('origin')">核对出发与返回地点</button></div><ul v-if="result.issues.some(x=>x.message!==result!.reply)"><li v-for="(issue,i) in result.issues.filter(x=>x.message!==result!.reply)" :key="i">{{issue.message}}</li></ul><p v-if="stale" role="alert" class="trip-warning">素材篮、条件或行程已变化，旧预览失效。请重新计算。</p><div v-if="result.status==='infeasible'&&rounds<2" class="negotiation-options"><button v-for="option in result.options" :key="option.id" type="button" :disabled="busy||stale" @click="choose(option)">{{option.label}} <ArrowRight :size="15"/></button></div><p v-else-if="result.status==='infeasible'&&rounds>=2">仍有冲突，可以调整时间或素材优先级。</p><div class="plan-alternatives"><button v-for="(plan,index) in alternatives" :key="index" class="plan-option" :class="{selected:selected===index}" :aria-pressed="selected===index" :disabled="busy||stale" type="button" @click="selected=index"><header><span>方案 {{index+1}} · {{plan.activities.length}} 项</span><Check v-if="selected===index" :size="18"/></header><ol><li v-for="stop in plan.activities" :key="stop.goal_id"><time>{{clock(stop.starts_at)}}</time><div><strong>{{result.activity_names?.[stop.goal_id]||nameOf(stop.place_id)}}</strong><small>{{Math.round(stop.duration_seconds/60)}} 分钟{{stop.required?' · 保留必去':''}}</small></div></li></ol><div class="plan-metrics"><span>游览与用餐 {{Math.round(plan.activities.reduce((n,a)=>n+a.duration_seconds,0)/60)}} 分钟</span><span><Clock3 :size="14"/>交通 {{Math.ceil(plan.travel_seconds/60)}} 分钟</span><span><Footprints :size="14"/>步行 {{Math.round(plan.walking_distance_m)}} 米</span><span>预计 {{clock(plan.returns_at)}} 返程</span><span>{{plan.cost_unknown?'费用待添加':'已知费用上限 ¥'+(plan.known_cost_upper_fen/100).toFixed(0)}}</span></div><p v-if="omitted(index).length">暂不安排：{{omitted(index).map(x=>x.name).join('、')}}<small>候补、未选择或在当前约束下未纳入；素材不会删除。</small></p><small>{{plan.evidence_mode==='synthetic'?'隔离演示资料':'交通为有依据的估计，非到达保证'}}</small></button></div><p v-for="warning in result.planning?.result.warnings||[]" :key="warning" class="pending-copy">{{warning}}</p><ul v-if="chosenChanges" class="planning-change-list" aria-label="正式行程变更对比"><li v-if="chosenChanges.added.length">新增：{{chosenChanges.added.map(id=>result!.activity_names?.[id]||'待核对活动').join('、')}}</li><li v-if="chosenChanges.removed.length">移除：{{chosenChanges.removed.map(id=>result!.activity_names?.[id]||'待核对活动').join('、')}}</li><li v-if="chosenChanges.reordered.length">调整顺序：{{chosenChanges.reordered.map(id=>result!.activity_names?.[id]||'待核对活动').join('、')}}</li><li v-for="change in chosenChanges.start_changes||[]" :key="change.goal_id">{{result.activity_names?.[change.goal_id]||'活动'}}：{{clock(change.before)}} → {{clock(change.after)}}</li><li v-for="change in chosenChanges.target_changes||[]" :key="'target:'+change.goal_id">更换地点或场次：{{result.activity_names?.[change.goal_id]||'活动'}}，请核对上方新安排。</li></ul><p v-if="chosenChanges?.removed.length" class="trip-warning">将移除 {{chosenChanges!.removed.length}} 个原活动，确认前请比较新安排。</p><div v-if="alternatives.length" class="planning-confirm"><button type="button" class="button primary" :disabled="busy||stale" @click="confirm">确认方案 {{selected+1}}，更新正式行程</button><button type="button" class="text-link" :disabled="busy||initializing" @click="cancel">保留原行程</button></div><div v-else class="planning-confirm"><button type="button" class="text-link" :disabled="busy||initializing" @click="run"><RefreshCw :size="14"/>重新核验</button><RouterLink to="/basket" class="text-link">整理素材篮</RouterLink><button type="button" class="text-link" @click="cancel">取消本次规划</button></div></section><button v-if="busy&&!confirming" type="button" class="text-link" @click="cancel">取消等待，保留原行程</button></section></template>

<style scoped>
.conversation-planning{border:0;padding-top:0}.planning-materials{display:flex;align-items:start;gap:12px;margin:0 0 22px;padding-bottom:16px;border-bottom:1px solid #dfd6c5;font-size:13px;color:#6c7d69}.planning-materials p{flex:1;margin:0;line-height:1.8}.planning-materials strong{font-weight:500;color:#29483b}.planning-materials a{white-space:nowrap;font-size:12px;min-height:32px;padding:4px 0}.planning-known{display:flex;flex-wrap:wrap;gap:7px;margin-bottom:20px}.planning-known button{font:inherit;font-size:12px;border:1px solid #dbd5c5;border-radius:16px;padding:7px 11px;color:#777b63;min-height:36px}.planning-question,.planning-assessment{scroll-margin-bottom:100px}.planning-question{display:grid;gap:14px!important}.planning-question-text{font:22px/1.6 'Songti SC',serif;color:#29483b;margin:0 0 4px!important}.planning-question label{font-size:12px;color:#8d7d65}.planning-question input,.planning-question select{display:block;width:100%;min-width:0;box-sizing:border-box;margin-top:7px;font-size:16px;min-height:44px;background:#fffcf5}.planning-question .button{justify-self:start;min-height:44px;background:#29483b;color:#fff8e9}.planning-quick{display:flex;gap:10px}.planning-quick button{padding:10px 24px;border:1px solid #c9cdbb;border-radius:6px;font-size:14px;color:#456653;min-height:44px}.planning-time-pair{display:grid;grid-template-columns:1fr 1fr;gap:14px}.planning-question .pending-copy{margin:0;color:#97856b;font-size:13px}
.planning-location-fields{display:grid;gap:14px}.early-time-confirm{display:flex;align-items:center;gap:8px}.planning-question .early-time-confirm input{width:20px;min-height:24px;margin:0;flex-shrink:0}
</style>
